-- =====================================================================================
--  Report_QA_E2E_SALES_GROUPED_Layout.sql  -  generated by ERP Studio (report designer, rf-report/1)
--  Report: QA sales by customer
--  Saves the default JSON layout (Scope = 'all') into Sys_ReportLayouts. Safe to run many times.
--  Needs: Database/Phase7_Reports.sql and Database/Phase10_Reports_Json.sql.
-- =====================================================================================
SET NOCOUNT ON;

IF OBJECT_ID(N'dbo.Sys_Reports', N'U') IS NULL OR OBJECT_ID(N'dbo.Sys_ReportLayouts', N'U') IS NULL OR COL_LENGTH(N'dbo.Sys_ReportLayouts', N'LayoutJson') IS NULL
BEGIN
    RAISERROR(N'Sys_Reports / Sys_ReportLayouts.LayoutJson not found - run Phase7_Reports.sql and Phase10_Reports_Json.sql first. Nothing changed.', 16, 1);
    RETURN;
END

DECLARE @Code NVARCHAR(100) = N'QA_E2E_SALES_GROUPED';
DECLARE @NameA NVARCHAR(200) = N'المبيعات حسب العميل (QA)';
DECLARE @NameE NVARCHAR(200) = N'QA sales by customer';
DECLARE @By NVARCHAR(100) = N'Studio:studio_test';
DECLARE @Json NVARCHAR(MAX) = N'{"schema":"rf-report/1","code":"QA_E2E_SALES_GROUPED","nameAr":"المبيعات حسب العميل (QA)","nameEn":"QA sales by customer","kind":"list","page":{"size":"A4","orientation":"landscape","dir":"auto"},"data":{"source":{"type":"proc","name":"dbo.QA_E2E_Rpt_SalesByCustomer"},"params":[{"name":"FromDate","from":"filter","value":"SaleDate.from"},{"name":"ToDate","from":"filter","value":"SaleDate.to"}],"tables":{"Data":"lines"}},"styles":{"base":{"size":9.5,"color":"#0b1c30"},"th":{"size":9,"bold":true,"background":"#1f3a5f","color":"#ffffff"},"td":{"size":9},"total":{"size":9.5,"bold":true,"background":"#eef2f7"}},"bands":[{"type":"reportHeader","elements":[{"type":"row","gap":4,"items":[{"type":"image","src":"Company.LogoBase64","width":20,"height":16,"visibleIf":"Company.LogoBase64 <> ''''"},{"type":"text","width":"50%","text":{"ar":"{{Company.CompNameA}}","en":"{{coalesce(Company.CompNameE, Company.CompNameA)}}"},"style":{"size":13,"bold":true,"color":"#1f3a5f"}},{"type":"text","width":"34%","text":{"ar":"المبيعات حسب المدينة والعميل","en":"Sales by city and customer"},"style":{"size":13,"bold":true,"align":"end","color":"#1f3a5f"}}]},{"type":"text","text":{"ar":"من {{Params.FromDate | date}} إلى {{Params.ToDate | date}} · طُبع: {{Company.PrintedAt}} بواسطة {{Company.PrintedBy}}","en":"From {{Params.FromDate | date}} to {{Params.ToDate | date}} · Printed: {{Company.PrintedAt}} by {{Company.PrintedBy}}"},"style":{"size":8,"color":"#64748b"}},{"type":"line","thickness":0.5,"color":"#1f3a5f"},{"type":"spacer","height":2}]},{"type":"groupHeader","groupBy":"City","elements":[{"type":"text","text":{"ar":"المدينة: {{City}}","en":"City: {{City}}"},"style":{"bold":true,"size":11,"background":"#dbe4f0","padding":1.2}}]},{"type":"groupHeader","groupBy":"CustomerNameAr","elements":[{"type":"text","text":{"ar":"{{CustomerNameAr}}","en":"{{CustomerNameEn}}"},"style":{"bold":true,"size":10,"background":"#eef2f7","padding":1}}]},{"type":"detail","table":"lines","layout":"table","zebra":true,"showTotals":true,"sortBy":["City","CustomerNameAr","SaleDate"],"columns":[{"field":"InvoiceNo","title":{"ar":"رقم الفاتورة","en":"Invoice"},"width":"14%"},{"field":"SaleDate","title":{"ar":"التاريخ","en":"Date"},"width":"14%","format":"date"},{"expr":"if(lang = ''en'', PaymentNameEn, PaymentNameAr)","title":{"ar":"الدفع","en":"Payment"},"width":"12%"},{"field":"TotalAmount","title":{"ar":"الإجمالي","en":"Total"},"width":"15%","format":"n2","align":"end","aggregate":"sum"},{"field":"Discount","title":{"ar":"الخصم","en":"Discount"},"width":"15%","format":"n2","align":"end","aggregate":"sum"},{"field":"VatAmount","title":{"ar":"الضريبة","en":"VAT"},"width":"15%","format":"n2","align":"end","aggregate":"sum"},{"field":"NetAmount","title":{"ar":"الصافي","en":"Net"},"width":"15%","format":"n2","align":"end","aggregate":"sum"}]},{"type":"groupFooter","groupBy":"CustomerNameAr","elements":[{"type":"text","text":{"ar":"إجمالي {{CustomerNameAr}}: {{count()}} فاتورة · الصافي {{sum(NetAmount) | n2}}","en":"Total {{CustomerNameEn}}: {{count()}} invoices · net {{sum(NetAmount) | n2}}"},"style":{"bold":true,"align":"end","border":{"top":true},"padding":1}}]},{"type":"groupFooter","groupBy":"City","elements":[{"type":"text","text":{"ar":"إجمالي {{City}}: {{sum(NetAmount) | n2}}","en":"Total {{City}}: {{sum(NetAmount) | n2}}"},"style":{"bold":true,"align":"end","background":"#dbe4f0","padding":1}}]},{"type":"reportFooter","elements":[{"type":"text","text":{"ar":"عدد الفواتير: {{count()}} · إجمالي الصافي: {{sum(NetAmount) | n2}}","en":"Invoices: {{count()}} · Net total: {{sum(NetAmount) | n2}}"},"style":{"bold":true,"size":11}}]},{"type":"pageFooter","elements":[{"type":"line","thickness":0.2,"color":"#cbd5e1"},{"type":"pageNumber","style":{"size":7.5,"color":"#64748b","align":"center"}}]}]}';

BEGIN TRY
    BEGIN TRANSACTION;

    -- 1) report definition (only when it is new; an existing definition is not changed)
    IF NOT EXISTS (SELECT 1 FROM dbo.Sys_Reports WHERE ReportCode = @Code)
    BEGIN
        INSERT INTO dbo.Sys_Reports (ReportCode, NameA, NameE, Kind, ProcName, IsActive)
        VALUES (@Code, @NameA, @NameE, 'list', N'dbo.QA_E2E_Rpt_SalesByCustomer', 1);
        INSERT INTO dbo.Sys_ReportParams (ReportCode, ParamName, Source, SourceValue, SortOrder)
        VALUES (@Code, N'FromDate', 'filter', N'SaleDate.from', 0);
        INSERT INTO dbo.Sys_ReportParams (ReportCode, ParamName, Source, SourceValue, SortOrder)
        VALUES (@Code, N'ToDate', 'filter', N'SaleDate.to', 1);
    END

    -- 2) default JSON layout for everybody (company/branch layouts are managed from the Studio, not here)
    IF EXISTS (SELECT 1 FROM dbo.Sys_ReportLayouts WHERE ReportCode = @Code AND Scope = 'all' AND LayoutFormat = 'json')
        UPDATE dbo.Sys_ReportLayouts
           SET LayoutJson = @Json, PaperSize = 'A4', Orientation = 'landscape', IsDefault = 1, UpdatedAt = GETDATE(), UpdatedBy = @By
         WHERE ReportCode = @Code AND Scope = 'all' AND LayoutFormat = 'json';
    ELSE
        INSERT INTO dbo.Sys_ReportLayouts (ReportCode, Scope, CompCode, BranchCode, PaperSize, Orientation, LayoutFormat, LayoutJson, IsDefault, UpdatedAt, UpdatedBy)
        VALUES (@Code, 'all', NULL, NULL, 'A4', 'landscape', 'json', @Json, 1, GETDATE(), @By);

    COMMIT TRANSACTION;
    PRINT N'Report layout saved: ' + @Code;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    DECLARE @Err NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(@Err, 16, 1);
END CATCH
